escenas.Mundo:
// Mundo compartido: «Por qué se tapa otra vez y cómo destaparlo bien».
// Maqueta en corte de un baño pequeño: lavamanos blanco transparente, sifón en U y desagüe a la vista,
// pared en corte a la derecha con la bajante. Qué se ve al EMPEZAR cada paso:
// 0: agua gris estancada, tapón entero en el sifón, frasco verde volcado encima.
// 1: igual, y el químico verde cae del frasco.
// 2: el tapón ya tiene un túnel en el centro; el agua sigue alta.
// 3: el agua bajó un poco; la persona de camiseta azul está al lado.
// 4: el tapón volvió a crecer y cerró el túnel; el agua subió; la persona está sorprendida.
// 5-6: llega la sopapa roja y queda de pie al lado (desde el paso 6, el rebose está tapado con el trapo azul).
// 7-8: la sopapa está sentada sobre el desagüe, cubierta de agua (en el paso 8, con las flechas de presión).
// 9: el tapón está suelto y hecho trozos dentro del sifón.
// 10: tubo libre, lavamanos limpio y vacío, la llave brilla, la sopapa al lado.
// 11: igual, con una gota en la llave y agua limpia corriendo por el tubo.
import React from 'react';
import {Pieza, Linea, Flecha} from '../lib3d';
import type {Paleta, V3} from '../lib3d';
import {Recorte, Persona2D, Efecto, Sombra, Habitacion, Grifo, Tuberia, ESTILO25D} from '../lib25d';

export const PARTES = [
  'pared', 'lavamanos', 'llave', 'desague', 'rebose', 'sifon', 'tubo', 'tapon', 'tunel', 'agua',
  'frasco', 'quimico', 'persona', 'sopapa', 'copa', 'trapo', 'presion',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

const PI = Math.PI;
const FPS = 30;
const BLANCO = '#FBF8F2';
const CROMO = '#C9CED6';
const VIDRIO = '#DCE9F0';
const GRASA = '#8A8580';
const GRASA2 = '#6F6964';
const PELO = '#3B2F28';
const MADERA = '#B9824E';
const ROJO = '#E0482B';
const VERDE = '#3FA34D';
const col = (p: ParteProps, c: string) => (p.resaltado ? p.paleta.acentos[2] : c);

// ---------- estados por paso ----------
/** Nivel del agua en la poceta (0..1 del rectángulo de agua). */
export const nivelAgua = (paso: number) => (paso >= 10 ? 0 : paso === 3 ? 0.6 : paso >= 4 ? 0.85 : 0.8);
export type EstadoTapon = 'entero' | 'tunel' | 'cerrado' | 'trozos' | 'nada';
export const estadoTapon = (paso: number): EstadoTapon =>
  paso <= 1 ? 'entero' : paso <= 3 ? 'tunel' : paso <= 8 ? 'cerrado' : paso === 9 ? 'trozos' : 'nada';
/** Dónde está la sopapa: null (no está), 'lado' (de pie junto al lavamanos) o 'desague' (sentada en la poceta). */
export const lugarSopapa = (paso: number): null | 'lado' | 'desague' =>
  paso <= 4 ? null : paso <= 6 ? 'lado' : paso <= 9 ? 'desague' : 'lado';
export const POS_SOPAPA_LADO: V3 = [-0.62, 0, 0.45];
export const POS_SOPAPA_DESAGUE: V3 = [0, 0.866, 0];
/** Puntos clave para las escenas. */
export const PUNTOS = {
  desague: [0, 0.87, 0] as V3,
  rebose: [-0.3, 1.04, 0.29] as V3,
  tapon: [0, 0.59, 0] as V3,
  sifon: [0.17, 0.27, 0] as V3,
  bocaLlave: [0, 1.42, -0.36] as V3,
  bocaFrasco: [0.12, 1.25, 0.05] as V3,
};

// ---------- fondo: pared de baldosas, pared en corte, base ----------
export const Pared: React.FC<ParteProps> = (p) => (
  <group>
    <Pieza forma="caja" medidas={[2.05, 1.95, 0.05]} color={col(p, '#F6EFE2')} posicion={[-0.175, 0.975, -0.62]} />
    {[0.35, 0.7, 1.05, 1.4, 1.75].map((y) => (
      <Pieza key={y} forma="caja" medidas={[2.05, 0.008, 0.01]} color="#D9CDB8" posicion={[-0.175, y, -0.592]} contorno={false} />
    ))}
    {[-0.9, -0.5, -0.1, 0.3, 0.7].map((x) => (
      <Pieza key={x} forma="caja" medidas={[0.008, 1.95, 0.01]} color="#D9CDB8" posicion={[x, 0.975, -0.592]} contorno={false} />
    ))}
    <Pieza forma="caja" medidas={[2.05, 0.1, 0.03]} color={p.paleta.acentos[0]} posicion={[-0.175, 1.22, -0.585]} />
    {/* pared en corte: hueco con aislante y dos parales de madera */}
    <Pieza forma="caja" medidas={[0.34, 1.95, 0.04]} color="#B48A62" posicion={[1.02, 0.975, -0.62]} />
    <Pieza forma="caja" medidas={[0.05, 1.95, 0.32]} color="#C89B6D" posicion={[0.84, 0.975, -0.45]} />
    <Pieza forma="caja" medidas={[0.05, 1.95, 0.32]} color="#C89B6D" posicion={[1.19, 0.975, -0.45]} />
    {/* repisa con jabón */}
    <Pieza forma="caja" medidas={[0.42, 0.03, 0.14]} color={BLANCO} posicion={[-0.78, 1.45, -0.53]} />
    <Pieza forma="cilindro" medidas={[0.045, 0.05, 0.16]} color="#F2C94C" posicion={[-0.86, 1.545, -0.52]} />
    <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.05]} color="#FFFFFF" posicion={[-0.86, 1.65, -0.52]} />
    <Pieza forma="caja" medidas={[0.1, 0.06, 0.07]} color="#E9E1D3" posicion={[-0.68, 1.495, -0.52]} />
    {/* base de la maqueta y zócalo */}
    <Pieza forma="caja" medidas={[2.4, 0.04, 1.4]} color="#E9E1D3" posicion={[0, 0.02, -0.05]} />
    <Pieza forma="caja" medidas={[2.05, 0.08, 0.03]} color="#C89B6D" posicion={[-0.175, 0.08, -0.585]} />
  </group>
);

// ---------- lavamanos (poceta transparente en corte) ----------
export const Lavamanos: React.FC<ParteProps> = (p) => (
  <group>
    <Pieza forma="cilindro" medidas={[0.42, 0.34, 0.24]} color={col(p, BLANCO)} posicion={[0, 0.98, 0]} opacidad={0.3} contorno={false} />
    <Pieza forma="toro" medidas={[0.42, 0.035]} color={col(p, BLANCO)} posicion={[0, 1.1, 0]} rotacion={[PI / 2, 0, 0]} />
    <Pieza forma="toro" medidas={[0.34, 0.012]} color="#B8B2A8" posicion={[0, 0.86, 0]} rotacion={[PI / 2, 0, 0]} contorno={false} />
    <Pieza forma="caja" medidas={[0.96, 0.08, 0.2]} color={col(p, BLANCO)} posicion={[0, 1.08, -0.44]} />
    {[-0.3, 0.3].map((x) => (
      <Pieza key={x} forma="caja" medidas={[0.05, 0.2, 0.26]} color={CROMO} posicion={[x, 0.96, -0.46]} />
    ))}
  </group>
);

export const Llave: React.FC<ParteProps & {gotea?: boolean; brilla?: boolean}> = ({gotea = false, brilla = false, ...p}) => (
  <group>
    <Grifo color={col(p, CROMO)} posicion={[-0.36, 1.12, -0.36]} escala={0.8} gotea={gotea} frame={p.frame ?? 0} fps={FPS} />
    {brilla ? <Efecto tipo="destello" posicion={[-0.2, 1.55, -0.3]} tam={0.3} frame={p.frame ?? 0} fps={FPS} color="#FFFFFF" /> : null}
  </group>
);

export const Desague: React.FC<ParteProps> = (p) => (
  <group position={PUNTOS.desague}>
    <Pieza forma="toro" medidas={[0.06, 0.016]} color={col(p, CROMO)} rotacion={[PI / 2, 0, 0]} />
    <Pieza forma="cilindro" medidas={[0.055, 0.055, 0.01]} color="#6F767E" contorno={false} />
    <Pieza forma="caja" medidas={[0.11, 0.012, 0.014]} color={col(p, CROMO)} posicion={[0, 0.006, 0]} contorno={false} />
  </group>
);

export const Rebose: React.FC<ParteProps> = (p) => (
  <group>
    <group position={PUNTOS.rebose} rotation={[0, Math.atan2(-0.3, 0.29), 0]}>
      <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.02]} color={col(p, '#4A4440')} rotacion={[PI / 2, 0, 0]} escala={[1.4, 1, 0.8]} />
    </group>
    <Tuberia
      puntos={[[-0.32, 1.03, 0.28], [-0.41, 0.97, 0.18], [-0.41, 0.86, 0.08], [-0.22, 0.8, 0.02], [-0.1, 0.78, 0]]}
      radio={0.024} color={col(p, '#E6E0D6')} frame={p.frame ?? 0} fps={FPS}
    />
  </group>
);

// ---------- sifón en U transparente ----------
export const Sifon: React.FC<ParteProps> = (p) => {
  const c = col(p, VIDRIO);
  const o = p.resaltado ? 0.45 : 0.3;
  return (
    <group>
      <Pieza forma="cilindro" medidas={[0.12, 0.12, 0.44]} color={c} posicion={[0, 0.64, 0]} opacidad={o} contorno={false} />
      <Pieza forma="toro" medidas={[0.17, 0.12, PI]} color={c} posicion={[0.17, 0.42, 0]} rotacion={[0, 0, PI]} opacidad={o} contorno={false} />
      <Pieza forma="cilindro" medidas={[0.12, 0.12, 0.16]} color={c} posicion={[0.34, 0.5, 0]} opacidad={o} contorno={false} />
      <Pieza forma="toro" medidas={[0.16, 0.12, PI / 2]} color={c} posicion={[0.5, 0.58, 0]} rotacion={[0, 0, PI / 2]} opacidad={o} contorno={false} />
      {/* tuercas que marcan las uniones */}
      {([[0, 0.84], [0, 0.43], [0.34, 0.58]] as [number, number][]).map(([x, y]) => (
        <Pieza key={`${x}${y}`} forma="cilindro" medidas={[0.135, 0.135, 0.04]} color={col(p, '#EDEDED')} posicion={[x, y, 0]} opacidad={0.85} />
      ))}
      <Pieza forma="cilindro" medidas={[0.135, 0.135, 0.04]} color={col(p, '#EDEDED')} posicion={[0.52, 0.74, 0]} rotacion={[0, 0, PI / 2]} />
    </group>
  );
};

export const Tubo: React.FC<ParteProps & {flujo?: number}> = ({flujo = 0, ...p}) => (
  <group>
    <Tuberia puntos={[[0.52, 0.74, 0], [0.78, 0.74, -0.1], [1.02, 0.74, -0.43]]} radio={0.1} color={col(p, '#D7DCE0')}
      flujo={flujo} colorFlujo={p.paleta.acentos[2]} frame={p.frame ?? 0} fps={FPS} />
    <Pieza forma="cilindro" medidas={[0.11, 0.11, 1.55]} color={col(p, '#D7DCE0')} posicion={[1.02, 0.8, -0.43]} />
    <Pieza forma="cilindro" medidas={[0.125, 0.125, 0.16]} color={col(p, '#C3C9CF')} posicion={[1.02, 0.74, -0.43]} />
  </group>
);

// ---------- tapón de pelo y grasa ----------
const pelos = (y: number, k: string): React.ReactNode =>
  ([[-0.08, 0.1, -0.05], [-0.03, 0.12, 0.02], [0.04, 0.11, 0.07], [0.08, 0.09, -0.03], [-0.06, -0.12, 0.03], [0.05, -0.11, -0.06]] as V3[]).map((d, i) => (
    <Linea key={k + i} desde={[d[0] * 0.6, y + d[1] * 0.5, d[2]]} hasta={[d[0] + 0.02 * (i % 2 ? 1 : -1), y + d[1], d[2] * 0.6]} grosor={0.004} color={PELO} />
  ));

export const Tapon: React.FC<ParteProps & {estado?: EstadoTapon}> = ({estado = 'entero', ...p}) => {
  if (estado === 'nada') return null;
  const g = col(p, GRASA);
  const g2 = col(p, GRASA2);
  const y = PUNTOS.tapon[1];
  if (estado === 'trozos')
    return (
      <group>
        {([[0.02, 0.32], [0.15, 0.26], [0.3, 0.36], [0.03, 0.46], [0.36, 0.52]] as [number, number][]).map(([x, yy], i) => (
          <Pieza key={i} forma="esfera" medidas={[0.035 + (i % 2) * 0.01]} color={i % 2 ? g : g2} posicion={[x, yy, 0]} escala={[1.2, 0.8, 1]} rotacion={[0, 0, i]} />
        ))}
        <Linea desde={[0.13, 0.27, 0]} hasta={[0.2, 0.3, 0.02]} grosor={0.004} color={PELO} />
        <Linea desde={[0.28, 0.35, 0]} hasta={[0.33, 0.41, 0]} grosor={0.004} color={PELO} />
      </group>
    );
  return (
    <group>
      <Pieza forma="esfera" medidas={[0.07]} color={g2} posicion={[-0.068, y, 0]} escala={[0.6, 1.55, 1.5]} />
      <Pieza forma="esfera" medidas={[0.07]} color={g2} posicion={[0.068, y, 0]} escala={[0.6, 1.55, 1.5]} />
      {estado !== 'tunel' ? <Pieza forma="esfera" medidas={[0.045]} color={g} posicion={[0, y, 0]} escala={[1, 2.3, 2.3]} /> : null}
      {estado === 'cerrado' ? (
        <>
          <Pieza forma="esfera" medidas={[0.06]} color={g} posicion={[0, y + 0.12, 0]} escala={[1.7, 0.8, 1.7]} />
          <Pieza forma="esfera" medidas={[0.055]} color={g2} posicion={[0.01, y - 0.12, 0]} escala={[1.8, 0.7, 1.8]} />
          {pelos(y + 0.06, 'b')}
        </>
      ) : null}
      {pelos(y, 'a')}
    </group>
  );
};

/** El túnel que abre el químico (se ve como una ranura oscura entre las dos mitades del tapón). */
export const Tunel: React.FC<ParteProps> = (p) => (
  <Pieza forma="caja" medidas={[0.05, 0.22, 0.01]} color={col(p, '#4B4541')} posicion={[0, PUNTOS.tapon[1], -0.09]} contorno={false} />
);

// ---------- agua gris (2D) ----------
export const AguaGris: React.FC<ParteProps & {nivel?: number; limpia?: boolean}> = ({nivel = 0.8, limpia = false, ...p}) => {
  if (nivel <= 0.01) return null;
  const c = p.resaltado || limpia
    ? {...ESTILO25D.colores}
    : {...ESTILO25D.colores, agua: '#8E9A95', aguaClara: '#C5CEC8'};
  const f = p.frame ?? 0;
  return (
    <group>
      <Recorte dibujo="agua" ancho={0.66} alto={0.22} posicion={[0, 0.97, 0.02]} opciones={{nivel, fuga: null, fuerza: 1, c}} frame={f} fps={FPS} />
      <Recorte dibujo="agua" ancho={0.2} alto={0.18} posicion={[0, 0.78, 0.02]} opciones={{nivel: 1, fuga: null, fuerza: 0.5, c}} frame={f} fps={FPS} />
    </group>
  );
};

// ---------- frasco de destapacaños y químico ----------
export const Frasco: React.FC<ParteProps> = (p) => (
  <group position={[0.3, 1.38, 0.05]} rotation={[0, 0, 2.2]}>
    <Pieza forma="cilindro" medidas={[0.11, 0.11, 0.3]} color={col(p, VERDE)} />
    <Pieza forma="caja" medidas={[0.16, 0.12, 0.02]} color="#F6F2EA" posicion={[0, 0, 0.105]} />
    <Pieza forma="cilindro" medidas={[0.045, 0.1, 0.07]} color={col(p, VERDE)} posicion={[0, 0.185, 0]} />
    <Pieza forma="cilindro" medidas={[0.05, 0.05, 0.05]} color="#2A6B33" posicion={[0, 0.24, 0]} />
  </group>
);

export const Quimico: React.FC<ParteProps> = (p) => (
  <Efecto tipo="chorro" posicion={[0.1, 1.15, 0.05]} tam={0.14} color={col(p, '#7BD35A')} frame={p.frame ?? 0} fps={FPS} />
);

// ---------- persona de camiseta azul (2D, sin cara) ----------
export const Persona: React.FC<ParteProps & {pose?: string}> = ({pose = 'parado', ...p}) => (
  <group>
    <Persona2D pose={pose} color={col(p, '#2F7FD0')} alto={1.35} posicion={[-0.98, 0, 0.12]} frame={p.frame ?? 0} fps={FPS} />
    <Sombra posicion={[-0.98, 0, 0.12]} radio={0.3} />
  </group>
);

// ---------- sopapa: copa roja y mango de madera ----------
export const Copa: React.FC<ParteProps> = (p) => (
  <group>
    <Pieza forma="media_esfera" medidas={[0.13]} color={col(p, ROJO)} escala={[1, 0.8, 1]} />
    <Pieza forma="toro" medidas={[0.125, 0.014]} color={col(p, '#B8321D')} rotacion={[PI / 2, 0, 0]} posicion={[0, 0.004, 0]} />
    <Pieza forma="cilindro" medidas={[0.04, 0.05, 0.04]} color={col(p, ROJO)} posicion={[0, 0.115, 0]} />
  </group>
);
export const Mango: React.FC<ParteProps> = (p) => (
  <group>
    <Pieza forma="cilindro" medidas={[0.024, 0.024, 0.72]} color={col(p, MADERA)} posicion={[0, 0.48, 0]} />
    <Pieza forma="esfera" medidas={[0.035]} color={col(p, '#9C6A3C')} posicion={[0, 0.85, 0]} />
  </group>
);
/** Sopapa completa con el origen en el borde de la copa (para animarla en las escenas). */
export const SopapaForma: React.FC<ParteProps & {resaltarCopa?: boolean; sinCopa?: boolean}> = ({resaltarCopa, sinCopa, ...p}) => (
  <group>
    {sinCopa ? null : <Copa {...p} resaltado={p.resaltado || resaltarCopa} />}
    <Mango {...p} />
  </group>
);
export const Sopapa: React.FC<ParteProps & {paso?: number; resaltarCopa?: boolean; sinCopa?: boolean}> = ({paso = 11, ...p}) => {
  const lugar = lugarSopapa(paso) ?? 'lado';
  return lugar === 'lado' ? (
    <group>
      <group position={POS_SOPAPA_LADO} rotation={[0, 0, -0.14]}>
        <SopapaForma {...p} />
      </group>
      <Sombra posicion={POS_SOPAPA_LADO} radio={0.22} />
    </group>
  ) : (
    <group position={POS_SOPAPA_DESAGUE}>
      <SopapaForma {...p} />
    </group>
  );
};

// ---------- trapo mojado en el rebose ----------
export const Trapo: React.FC<ParteProps> = (p) => {
  const c = col(p, '#2F6FB8');
  return (
    <group position={PUNTOS.rebose}>
      <Pieza forma="esfera" medidas={[0.045]} color={c} escala={[1.2, 0.9, 0.9]} posicion={[-0.02, 0, 0.02]} />
      <Pieza forma="esfera" medidas={[0.04]} color={c} escala={[0.9, 1.3, 0.8]} posicion={[-0.06, -0.05, 0.05]} rotacion={[0, 0, 0.4]} />
      <Pieza forma="esfera" medidas={[0.03]} color={col(p, '#4F8FD8')} escala={[1.4, 0.7, 1]} posicion={[0.01, 0.035, 0.03]} />
    </group>
  );
};

// ---------- flechas azules de presión (van y vienen) ----------
export const Presion: React.FC<ParteProps> = (p) => {
  const v = Math.sin((p.frame ?? 0) * 0.35) * 0.035;
  const c = p.paleta.acentos[2];
  return (
    <group>
      <Flecha desde={[-0.04, 0.84 + v, 0.03]} hasta={[-0.04, 0.73 + v, 0.03]} color={c} grosor={0.016} />
      <Flecha desde={[0.04, 0.73 - v, 0.03]} hasta={[0.04, 0.84 - v, 0.03]} color={c} grosor={0.016} />
      <Flecha desde={[-0.2, 0.96 + v, 0.05]} hasta={[-0.08, 0.9 + v, 0.05]} color={c} grosor={0.016} />
      <Flecha desde={[0.2, 0.96 + v, 0.05]} hasta={[0.08, 0.9 + v, 0.05]} color={c} grosor={0.016} />
    </group>
  );
};

// ---------- el mundo completo ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, fps, paleta, ocultar = [], resaltar = []}) => {
  const ve = (n: string) => !ocultar.includes(n);
  const pp = (n: string): ParteProps => ({paleta, frame, resaltado: resaltar.includes(n)});
  const tapon = estadoTapon(paso);
  const sopapa = lugarSopapa(paso);
  void fps;
  return (
    <group>
      <Habitacion />
      {ve('pared') ? <Pared {...pp('pared')} /> : null}
      {ve('tubo') ? <Tubo {...pp('tubo')} flujo={paso >= 11 ? 1 : 0} /> : null}
      {ve('sifon') ? <Sifon {...pp('sifon')} /> : null}
      {ve('tapon') ? <Tapon {...pp('tapon')} estado={tapon} /> : null}
      {ve('tunel') && tapon === 'tunel' ? <Tunel {...pp('tunel')} /> : null}
      {ve('agua') ? <AguaGris {...pp('agua')} nivel={nivelAgua(paso)} /> : null}
      {ve('desague') ? <Desague {...pp('desague')} /> : null}
      {ve('rebose') ? <Rebose {...pp('rebose')} /> : null}
      {ve('trapo') && paso >= 6 && paso <= 9 ? <Trapo {...pp('trapo')} /> : null}
      {ve('lavamanos') ? <Lavamanos {...pp('lavamanos')} /> : null}
      {ve('llave') ? <Llave {...pp('llave')} gotea={paso >= 11} brilla={paso === 10} /> : null}
      {ve('frasco') && paso <= 1 ? <Frasco {...pp('frasco')} /> : null}
      {ve('quimico') && paso === 1 ? <Quimico {...pp('quimico')} /> : null}
      {ve('persona') && (paso === 3 || paso === 4) ? <Persona {...pp('persona')} pose={paso === 4 ? 'sorprendida' : 'parado'} /> : null}
      {ve('sopapa') && sopapa ? (
        <Sopapa {...pp('sopapa')} paso={paso} resaltarCopa={resaltar.includes('copa')} sinCopa={!ve('copa')} />
      ) : null}
      {ve('presion') && paso === 8 ? <Presion {...pp('presion')} /> : null}
      <Sombra posicion={[0, 0, -0.1]} radio={0.75} fuerza={0.7} />
      <Sombra posicion={[1.02, 0, -0.43]} radio={0.25} />
    </group>
  );
};

escenas.Escena1:
// Escena 2: «A menudo el líquido no disuelve todo el tapón. Solo le abre un huequito.»
// 3D: el lavamanos en corte, el tapón y el frasco. 2D: el chorro verde, las burbujas y las gotas.
import React from 'react';
import {EscenaProps, Pieza, Flecha, Etiqueta, aparecer, desaparecer, momento, mover} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Tapon, Tunel, Frasco, Quimico, PUNTOS} from './Mundo';

const PASO = 1;
const VERDE_Q = '#7BD35A';
const GRASA = '#8A8580';

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , resalte] = paleta.acentos;
  const tLiquido = momento(palabras, fps, 'líquido', 18);
  const tNo = momento(palabras, fps, 'no', 31);
  const tDisuelve = momento(palabras, fps, 'disuelve', 39);
  const tTapon = momento(palabras, fps, 'tapón', 66);
  const tAbre = momento(palabras, fps, 'abre', 100);
  const tHueco = momento(palabras, fps, 'huequito', 110);

  // Frasco: tiembla mientras vierte, al final se va hacia arriba a la derecha y desaparece.
  const sale = aparecer(frame, tTapon + 6, 18);
  const frascoX = mover(frame, [tTapon + 6, tTapon + 24], [0, 0.7]);
  const frascoY = mover(frame, [tTapon + 6, tTapon + 24], [0, 0.6]);
  const temblor = sale > 0 ? 0 : Math.sin(frame * 0.9) * 0.025;
  const frascoEsc = 1 - sale;

  // Chorro verde: sale desde el inicio y se corta cuando el frasco se va.
  const chorro = desaparecer(frame, tTapon + 4, 8);

  // Gotas verdes bajando por el desagüe hasta el tapón (golpe desde el fotograma 0).
  const flujo = Math.min(1, 0.6 + aparecer(frame, tLiquido, 10) * 0.4) * desaparecer(frame, tAbre + 30, 12);
  const gotas: React.ReactNode[] = [];
  for (let i = 0; i < 6; i++) {
    const per = 16;
    const f = (frame + i * (per / 6) * 2.7) % per;
    const u = f / per;
    const y = 0.86 - u * 0.17;
    const x = (i % 3 - 1) * 0.035;
    gotas.push(
      <Pieza key={'g' + i} forma="esfera" medidas={[0.014]} color={VERDE_Q} posicion={[x, y, 0.02]}
        escala={flujo * (1 - u * 0.3)} contorno={false} brillo={VERDE_Q} intensidadBrillo={0.3} />,
    );
  }
  // Tras abrirse el túnel, unas gotas lo cruzan hacia el fondo del sifón.
  const cruza = aparecer(frame, tAbre + 6, 8) * desaparecer(frame, duracion - 6, 6);
  for (let i = 0; i < 3; i++) {
    const per = 14;
    const u = ((frame + i * 5) % per) / per;
    gotas.push(
      <Pieza key={'t' + i} forma="esfera" medidas={[0.012]} color={VERDE_Q} posicion={[0, 0.7 - u * 0.3, 0.02]}
        escala={cruza} contorno={false} />,
    );
  }

  // El tapón se sacude al recibir el líquido; el centro se disuelve en «abre».
  const sacude = frame < tAbre + 14 ? Math.sin(frame * 1.3) * 0.006 * aparecer(frame, tDisuelve, 6) : 0;
  const hueco = aparecer(frame, tAbre, 12);
  const centroEsc = 1 - hueco;
  const resaltaTapon = frame >= tTapon && frame < tTapon + 38;
  const resaltaTunel = frame >= tHueco && frame < tHueco + 40;

  // Cruz roja: «no disuelve todo».
  const cruz = aparecer(frame, tNo, 8) * desaparecer(frame, tAbre - 4, 8);
  // Flecha y etiqueta del huequito.
  const senal = aparecer(frame, tHueco, 10);
  const burbujas = aparecer(frame, tDisuelve, 8) * desaparecer(frame, tAbre + 20, 10);
  const yT = PUNTOS.tapon[1];

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['tapon', 'tunel', 'frasco', 'quimico']} />

      {/* frasco que vierte y luego se retira */}
      {frascoEsc > 0.01 ? (
        <group position={[frascoX + temblor, frascoY, 0]} scale={frascoEsc}>
          <Frasco paleta={paleta} frame={frame} />
        </group>
      ) : null}
      {chorro > 0.01 ? (
        <group scale={[1, chorro, 1]} position={[0, 1.15 * (1 - chorro), 0]}>
          <Quimico paleta={paleta} frame={frame} />
        </group>
      ) : null}

      {/* el líquido que baja por dentro */}
      {gotas}

      {/* tapón: las dos mitades fijas y el centro que se disuelve */}
      <group position={[sacude, 0, 0]}>
        <Tapon paleta={paleta} frame={frame} estado="tunel" resaltado={resaltaTapon} />
        {centroEsc > 0.01 ? (
          <Pieza forma="esfera" medidas={[0.045]} color={resaltaTapon ? resalte : GRASA} posicion={[0, yT, 0]}
            escala={[centroEsc, 2.3 * (0.4 + 0.6 * centroEsc), 2.3 * centroEsc]} />
        ) : null}
      </group>
      {hueco > 0.01 ? (
        <group position={[0, yT * (1 - hueco), 0]} scale={[1, hueco, 1]}>
          <Tunel paleta={paleta} frame={frame} resaltado={resaltaTunel} />
        </group>
      ) : null}

      {/* burbujas verdes del químico mordiendo el tapón */}
      {burbujas > 0.01 ? (
        <Efecto tipo="burbujas" posicion={[0, yT + 0.1, 0.14]} tam={0.16 * burbujas} color={VERDE_Q} frame={frame} fps={fps} />
      ) : null}

      {/* cruz roja: no lo disuelve todo */}
      {cruz > 0.01 ? (
        <group position={[-0.34, yT + 0.02, 0.2]} scale={cruz}>
          <Pieza forma="caja" medidas={[0.2, 0.04, 0.03]} color="#E0482B" rotacion={[0, 0, 0.785]} />
          <Pieza forma="caja" medidas={[0.2, 0.04, 0.03]} color="#E0482B" rotacion={[0, 0, -0.785]} />
        </group>
      ) : null}

      {/* destello cuando se abre el hueco */}
      {frame >= tAbre && frame < tAbre + 18 ? (
        <Efecto tipo="destello" posicion={[0, yT, 0.16]} tam={0.22} color="#FFFFFF" frame={frame - tAbre} fps={fps} />
      ) : null}

      {/* flecha naranja al túnel y su etiqueta */}
      <Flecha desde={[0.5, 0.86, 0.18]} hasta={[0.05, yT + 0.02, 0.1]} color={naranja} grosor={0.022} progreso={senal} />
      <Etiqueta texto="huequito" punto={[-0.02, yT - 0.04, 0.1]} desplazamiento={[-0.55, -0.22, 0.1]} escala={senal} />
    </group>
  );
};

escenas.Escena2:
// Escena 3 · «El agua baja un poquito y tú crees que ya sirvió.»
// 3D: lavamanos en corte, sifón y tapón con túnel (Mundo paso 2 → paso 3).
// 2D: el agua gris que baja despacio y la persona de camiseta azul que se alegra.
import React from 'react';
import {EscenaProps, Pieza, Flecha, Linea, Etiqueta, aparecer, momento, rebote} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, AguaGris, Persona, PUNTOS} from './Mundo';
import type {V3} from '../lib3d';

const PASO = 2;

// Recorrido del agua que se cuela: túnel del tapón → fondo de la U → salida hacia el tubo.
const CAMINO: V3[] = [
  [0, 0.84, 0],
  [0, 0.62, 0],
  [0, 0.45, 0],
  [0.08, 0.29, 0],
  [0.17, 0.25, 0],
  [0.27, 0.29, 0],
  [0.34, 0.45, 0],
  [0.4, 0.62, 0],
  [0.52, 0.74, 0],
];

const enCamino = (u: number): V3 => {
  const t = Math.min(0.9999, Math.max(0, u)) * (CAMINO.length - 1);
  const i = Math.floor(t);
  const k = t - i;
  const a = CAMINO[i];
  const b = CAMINO[i + 1];
  return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
};

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , azul, mostaza] = paleta.acentos;

  // Golpes sincronizados con la voz
  const tAgua = momento(palabras, fps, 'agua', 6);
  const tBaja = momento(palabras, fps, 'baja', 13);
  const tPoquito = momento(palabras, fps, 'poquito', 30);
  const tTu = momento(palabras, fps, 'tú', 56);
  const tSirvio = momento(palabras, fps, 'sirvió', 79);

  // 1) «agua»: el agua se resalta (se pinta limpia y brillante) ~1 s
  const resaltaAgua = frame >= tAgua && frame < tAgua + 32;
  // 2) «baja»: el nivel desciende despacio hasta el del paso 3 (0,8 → 0,6)
  const fin = Math.max(tBaja + 30, Math.min(duracion - 4, tBaja + 70));
  const baja = aparecer(frame, tBaja, fin - tBaja);
  const nivel = 0.8 - 0.2 * baja;
  // 3) «poquito»: se resalta el túnel por el que se cuela
  const resaltaTunel = frame >= tPoquito && frame < tPoquito + 32;
  const flecha = aparecer(frame, tBaja, 14);
  // 4) «tú»: aparece la persona; 5) «sirvió»: salta de alegría y aparece la etiqueta
  const entraPersona = rebote(frame, fps, tTu);
  const fs = frame - tSirvio;
  const salto = fs > 0 && fs < 10 ? Math.sin((fs / 10) * Math.PI) * 0.07 : 0;
  const etiqueta = aparecer(frame, tSirvio, 8);
  const destello = fs >= 0 && fs < 14;

  const resaltar: string[] = [];
  if (resaltaTunel) resaltar.push('tunel');

  // Gotitas que se cuelan por el túnel (pocas: es solo un hilito)
  const gotas = [0, 1, 2, 3, 4].map((i) => {
    const u = ((frame - tBaja) / 48 + i / 5) % 1;
    return {p: enCamino(u), vis: frame >= tBaja + i * 4};
  });

  // Ritmo constante en el hilo de agua de la boca del desagüe
  const pulso = 0.5 + 0.5 * Math.sin(frame * 0.4);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['agua', 'persona']} resaltar={resaltar} />

      {/* el agua gris que baja (al final, igual que el paso 3) */}
      <AguaGris paleta={paleta} frame={frame} nivel={nivel} resaltado={resaltaAgua} />

      {/* hilo de agua que se cuela por el túnel */}
      {frame >= tBaja
        ? gotas.map((g, i) =>
            g.vis ? (
              <Pieza key={i} forma="esfera" medidas={[0.017]} color={azul} posicion={g.p} contorno={false} brillo={azul} intensidadBrillo={0.4} />
            ) : null,
          )
        : null}
      <Linea desde={[0, 0.84, 0.02]} hasta={[0, 0.46, 0.02]} grosor={0.006} color={azul} discontinua progreso={flecha} />

      {/* flecha de flujo, al lado del sifón para no tapar el túnel */}
      <Flecha desde={[-0.2, 0.86, 0.16]} hasta={[-0.2, 0.5, 0.16]} color={azul} grosor={0.02} progreso={flecha} />
      {frame >= tBaja ? (
        <Efecto tipo="ondas" posicion={[PUNTOS.desague[0], PUNTOS.desague[1] + 0.02 + 0.2 * (1 - baja), 0.04]} tam={0.12 + 0.03 * pulso} color={azul} frame={frame} fps={fps} />
      ) : null}

      {/* la persona de camiseta azul: aparece y salta de alegría */}
      {entraPersona > 0.001 ? (
        <group position={[-0.98, salto, 0.12]} scale={Math.max(0.001, entraPersona)}>
          <group position={[0.98, 0, -0.12]}>
            <Persona paleta={paleta} frame={frame} pose="parado" />
          </group>
        </group>
      ) : null}
      {destello ? <Efecto tipo="destello" posicion={[-0.72, 1.3, 0.2]} tam={0.28} color={mostaza} frame={frame} fps={fps} /> : null}

      {/* «sirvió»: la falsa victoria, señalando el agua que apenas bajó */}
      <Etiqueta texto={'parece que\nsirvió'} punto={[0.22, 0.95, 0.12]} desplazamiento={[0.32, 0.6, 0.15]} alto={0.14} escala={etiqueta} />
    </group>
  );
};

escenas.Escena3:
// Escena 4 (paso 3): «Pero el resto sigue pegado a la tubería, y se vuelve a juntar.»
// 3D: el tapón en corte dentro del sifón transparente; los grumos nuevos caen y cierran el túnel.
// 2D: el agua gris que vuelve a subir, las gotas que pasan por el túnel y la persona que se sorprende.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Linea, Flecha, Etiqueta, momento} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Tapon, Tunel, AguaGris, Persona, PUNTOS, nivelAgua} from './Mundo';

const GRASA = '#8A8580';
const GRASA2 = '#6F6964';
const PELO = '#3B2F28';

const rango = (f: number, a: number, b: number, ease = Easing.inOut(Easing.cubic)) =>
  interpolate(f, [a, Math.max(a + 1, b)], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, mostaza] = paleta.acentos;
  const tPero = momento(palabras, fps, 'Pero', 1);
  const tResto = momento(palabras, fps, 'resto', 33);
  const tPegado = momento(palabras, fps, 'pegado', 55);
  const tTuberia = momento(palabras, fps, 'tubería', 71);
  const tY = momento(palabras, fps, 'y', 95);
  const tVuelve = momento(palabras, fps, 'vuelve', 101);
  const tJuntar = momento(palabras, fps, 'juntar', 112);
  const tFin = Math.min(duracion - 6, tJuntar + 22);
  const tCambio = tJuntar + 12; // desde aquí el tapón es exactamente el «cerrado» del paso 4

  const y = PUNTOS.tapon[1];

  // Golpe en «Pero»: el tapón se estremece (sigue ahí).
  const fp = frame - tPero;
  const sacudida = fp >= 0 ? Math.exp(-fp / 7) * Math.sin(fp / 1.8) * 0.09 : 0;
  // Respira un poco mientras está pegado (vivo, terco).
  const respira = 1 + Math.sin(frame * 0.18) * 0.012;

  const resaltaTapon = frame >= tResto && frame < tResto + 38;
  const resaltaSifon = frame >= tTuberia && frame < tTuberia + 36;

  // Marcas de agarre en las paredes del tubo («pegado»).
  const agarre = rango(frame, tPegado, tPegado + 8, Easing.out(Easing.back(2)));
  const sueltaAgarre = 1 - rango(frame, tVuelve, tVuelve + 8);
  const marcas = agarre * sueltaAgarre;
  const etiquetaPegado = marcas;

  // Grumos nuevos que bajan por el desagüe y se enganchan arriba, en medio y abajo.
  const llega = (retraso: number) => rango(frame, tY - 14 + retraso, tJuntar + 4 + retraso, Easing.in(Easing.quad));
  const bajaA = llega(0);
  const bajaB = llega(4);
  const bajaC = llega(8);
  const golpe = (t: number) => {
    const f = frame - t;
    return f > 0 ? 1 + Math.exp(-f / 4) * Math.sin(f / 1.4) * 0.18 : 1;
  };
  const tunelAbierto = 1 - rango(frame, tVuelve, tJuntar + 8);
  const cerrado = frame >= tCambio;

  // Agua: pasa por el túnel mientras está abierto y luego vuelve a subir.
  const nivel = interpolate(rango(frame, tVuelve, tFin), [0, 1], [nivelAgua(3), nivelAgua(4)]);
  const gotas = tunelAbierto > 0.25;

  // Flujo punteado por el túnel (desde el inicio, se apaga al cerrarse).
  const flujoProg = ((frame % 24) / 24) * 0.7 + 0.3;

  const etiquetaTapa = rango(frame, tVuelve, tVuelve + 10, Easing.out(Easing.back(1.6)));
  const sorprendida = frame >= tJuntar;
  const salto = sorprendida ? Math.max(0, Math.sin(Math.min(1, (frame - tJuntar) / 10) * Math.PI)) * 0.05 : 0;

  // Pelos nuevos que caen con los grumos.
  const pelosNuevos: [number, number, number, number][] = [
    [-0.07, 0.16, 0.04, 0],
    [0.06, 0.14, -0.03, 3],
    [-0.02, 0.1, 0.06, 6],
    [0.08, 0.08, 0.05, 9],
  ];

  return (
    <group>
      <Mundo paso={3} frame={frame} fps={fps} paleta={paleta} ocultar={['tapon', 'tunel', 'agua', 'persona']}
        resaltar={resaltaSifon ? ['sifon'] : []} />

      {/* agua gris de la poceta */}
      <AguaGris paleta={paleta} frame={frame} nivel={nivel} />

      {/* tapón: base con túnel que se cierra */}
      <group position={[0, y, 0]} scale={[(1 + sacudida) * respira, (1 - sacudida * 0.6) * respira, 1 + sacudida]}>
        <group position={[0, -y, 0]}>
          {cerrado ? (
            <Tapon paleta={paleta} frame={frame} estado="cerrado" resaltado={resaltaTapon} />
          ) : (
            <>
              <Tapon paleta={paleta} frame={frame} estado="tunel" resaltado={resaltaTapon} />
              {tunelAbierto > 0.02 ? (
                <group position={[0, y, 0]} scale={[tunelAbierto, Math.max(0.01, tunelAbierto), 1]}>
                  <group position={[0, -y, 0]}>
                    <Tunel paleta={paleta} frame={frame} resaltado={resaltaTapon} />
                  </group>
                </group>
              ) : null}
              {/* grumo del centro: cierra el túnel */}
              <group position={[0, interpolate(bajaB, [0, 1], [0.38, 0]) + y, 0]} scale={bajaB * golpe(tJuntar + 4)}>
                <Pieza forma="esfera" medidas={[0.045]} color={resaltaTapon ? resalte : GRASA} escala={[1, 2.3, 2.3]} />
              </group>
              {/* grumo de arriba */}
              <group position={[0, interpolate(bajaA, [0, 1], [0.36, 0]) + y + 0.12, 0]} scale={bajaA * golpe(tJuntar)}>
                <Pieza forma="esfera" medidas={[0.06]} color={GRASA} escala={[1.7, 0.8, 1.7]} />
              </group>
              {/* grumo de abajo */}
              <group position={[0.01, interpolate(bajaC, [0, 1], [0.4, 0]) + y - 0.12, 0]} scale={bajaC * golpe(tJuntar + 8)}>
                <Pieza forma="esfera" medidas={[0.055]} color={GRASA2} escala={[1.8, 0.7, 1.8]} />
              </group>
              {pelosNuevos.map(([px, py, pz, r], i) => {
                const b = llega(r);
                if (b <= 0.001) return null;
                const yy = interpolate(b, [0, 1], [0.42, 0.06]) + y;
                return (
                  <Linea key={i} desde={[px * 0.5, yy - py * 0.3, pz]} hasta={[px, yy + py * 0.4, pz * 0.6]} grosor={0.004} color={PELO} />
                );
              })}
            </>
          )}
        </group>
      </group>

      {/* agua que pasa por el túnel (mientras sigue abierto) */}
      {tunelAbierto > 0.05 ? (
        <Linea desde={[0, 0.82, 0.03]} hasta={[0, 0.36, 0.03]} grosor={0.009 * tunelAbierto} color={resalte}
          discontinua progreso={flujoProg} />
      ) : null}
      {gotas ? <Efecto tipo="gotas" posicion={[0, 0.4, 0.05]} tam={0.12} color={resalte} frame={frame} fps={fps} /> : null}

      {/* «pegado»: agarres mostaza contra las paredes del tubo */}
      {marcas > 0.01
        ? ([[-1, 0.08], [-1, -0.07], [1, 0.07], [1, -0.08]] as [number, number][]).map(([l, dy], i) => (
            <group key={i} position={[0.112 * l, y + dy, 0.03]} scale={marcas * (1 + Math.sin(frame * 0.4 + i) * 0.1)}>
              <Pieza forma="esfera" medidas={[0.022]} color={mostaza} escala={[0.7, 1.3, 0.7]} />
            </group>
          ))
        : null}
      {marcas > 0.01 ? (
        <>
          <Flecha desde={[-0.04, y, 0.06]} hasta={[-0.105, y, 0.06]} color={mostaza} grosor={0.012} progreso={marcas} />
          <Flecha desde={[0.04, y, 0.06]} hasta={[0.105, y, 0.06]} color={mostaza} grosor={0.012} progreso={marcas} />
        </>
      ) : null}
      <Etiqueta texto="pegado" punto={[-0.12, y + 0.02, 0.04]} desplazamiento={[-0.52, 0.12, 0.25]} escala={etiquetaPegado} />

      {/* rótulo: se vuelve a tapar */}
      <Etiqueta texto="se vuelve a tapar" punto={[0.06, y - 0.08, 0.06]} desplazamiento={[0.36, -0.36, 0.3]}
        escala={etiquetaTapa} alto={0.13} />

      {/* persona: de tranquila a sorprendida (manos a la cabeza) */}
      <group position={[0, salto, 0]}>
        <Persona paleta={paleta} frame={frame} pose={sorprendida ? 'sorprendida' : 'parado'} />
      </group>
    </group>
  );
};

escenas.Escena0:
// Escena 1 (gancho): «Un frasco entero de químico, y el tapón se burla de ti.»
// 3D: lavamanos en corte, sifón, frasco y tapón (los pone Mundo). 2D: el chorro verde, el agua gris, las gotas.
// Golpes: el frasco cae volcado (0 s) · se resalta el frasco · se sacude «entero» · el químico cae
// · se resalta el tapón · el tapón se sacude riéndose, aparece la cruz roja y la etiqueta.
import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Linea, aparecer, momento, mover, rebote} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Frasco, Quimico, Tapon, PUNTOS} from './Mundo';
import type {V3} from '../lib3d';

const P_FRASCO: V3 = [0.3, 1.38, 0.05];
const P_TAPON: V3 = PUNTOS.tapon;
const neg = (v: V3): V3 => [-v[0], -v[1], -v[2]];

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];
  const tFrasco = momento(palabras, fps, 'frasco', 22);
  const tEntero = momento(palabras, fps, 'entero', 41);
  const tQuimico = momento(palabras, fps, 'químico', 60);
  const tTapon = momento(palabras, fps, 'tapón', 84);
  const tBurla = momento(palabras, fps, 'burla', 98);
  const fin = 1 - aparecer(frame, duracion - 8, 8);

  // --- Frasco: cae ya volcado sobre el lavamanos en los primeros 9 fotogramas ---
  const k = mover(frame, [0, 9], [0, 1]);
  const golpe = frame > 9 ? Math.exp(-(frame - 9) / 5) * Math.sin((frame - 9) / 1.6) * 0.05 : 0;
  const dyF = 0.45 * (1 - k * k) + golpe;
  const fe = frame - tEntero;
  const sacude = fe > 0 ? 0.14 * Math.sin(fe * 1.3) * Math.exp(-fe / 9) : 0;
  const fq = frame - tQuimico;
  const vierte = fq > 0 ? 0.05 * Math.sin(fq * 0.5) * Math.exp(-fq / 25) : 0;
  const giroF = -0.7 * (1 - k) + sacude + vierte;
  const pulsoF = frame >= tFrasco ? 0.1 * Math.sin(Math.min(1, (frame - tFrasco) / 10) * Math.PI) : 0;
  const escF = 1 + 0.25 * (1 - k) + pulsoF;
  const frascoResaltado = frame >= tFrasco && frame < tFrasco + 36;

  // --- Tapón: resaltado al nombrarlo y se sacude «riéndose» en la burla ---
  const taponResaltado = frame >= tTapon && frame < tTapon + 38;
  const fb = frame - tBurla;
  const risa = fb > 0 ? Math.exp(-fb / 14) * Math.sin(fb * 0.9) : 0;
  const saltoT = fb > 0 ? Math.abs(Math.exp(-fb / 12) * Math.sin(fb * 0.45)) * 0.05 : 0;
  const escT: V3 = [1 - risa * 0.12, 1 + risa * 0.16, 1 - risa * 0.12];
  const giroT = risa * 0.12;

  // --- Químico: gotas verdes bajan por el desagüe y rebotan en el tapón sin pasar ---
  const gotas: React.ReactNode[] = [];
  if (fq > 6) {
    for (let i = 0; i < 4; i++) {
      const c = ((fq - 6) / 14 + i / 4) % 1;
      const y = 0.86 - c * 0.14;
      gotas.push(
        <Pieza key={i} forma="esfera" medidas={[0.018]} color="#7BD35A" posicion={[(i % 2 ? 0.02 : -0.025), y, 0.04]}
          escala={[1, 1.5, 1]} contorno={false} />,
      );
    }
  }

  // --- Cruz roja sobre el frasco (no funcionó) y etiqueta del rótulo ---
  const cruz = rebote(frame, fps, tBurla) * fin;
  const etiqueta = aparecer(frame, tBurla + 2, 8) * fin;
  const flechaDiv = aparecer(frame, tTapon, 10) * fin * (frame < tBurla ? 1 : 1 - aparecer(frame, tBurla, 6));

  return (
    <group>
      <Mundo paso={0} frame={frame} fps={fps} paleta={paleta} ocultar={['frasco', 'tapon']} />

      {/* frasco volcado que cae (al final queda exactamente donde lo pone Mundo) */}
      <group position={[P_FRASCO[0], P_FRASCO[1] + dyF, P_FRASCO[2]]} rotation={[0, 0, giroF]} scale={escF}>
        <group position={neg(P_FRASCO)}>
          <Frasco paleta={paleta} resaltado={frascoResaltado} frame={frame} />
        </group>
      </group>
      {frame < 26 ? (
        <Efecto tipo="ondas" posicion={[0.08, 1.07, 0.06]} tam={0.32} color="#C5CEC8" frame={frame} fps={fps} />
      ) : null}
      {fe > 0 && fe < 30 ? (
        <Efecto tipo="gotas" posicion={[0.14, 1.2, 0.08]} tam={0.16} color="#7BD35A" frame={frame} fps={fps} />
      ) : null}

      {/* el chorro verde del químico (queda corriendo, como en el paso 1) */}
      {frame >= tQuimico ? <Quimico paleta={paleta} frame={frame} /> : null}
      {gotas}
      {fq > 14 ? (
        <Efecto tipo="gotas" posicion={[0, 0.74, 0.05]} tam={0.12} color="#7BD35A" frame={frame} fps={fps} />
      ) : null}

      {/* el tapón de pelo y grasa, entero y burlón */}
      <group position={[P_TAPON[0], P_TAPON[1] + saltoT, P_TAPON[2]]} rotation={[0, 0, giroT]} scale={escT}>
        <group position={neg(P_TAPON)}>
          <Tapon paleta={paleta} estado="entero" resaltado={taponResaltado} frame={frame} />
        </group>
      </group>
      {fb > 0 && fb < 36 ? (
        <Efecto tipo="burbujas" posicion={[0, 0.74, 0.06]} tam={0.14} color="#C5CEC8" frame={frame} fps={fps} />
      ) : null}

      {/* camino del líquido: baja por el desagüe y se frena en el tapón */}
      {flechaDiv > 0 ? (
        <Linea desde={[-0.09, 0.9, 0.12]} hasta={[-0.09, 0.7, 0.12]} grosor={0.008} color={resalte} discontinua progreso={flechaDiv} />
      ) : null}

      {/* cruz roja: el frasco no sirvió */}
      {cruz > 0.001 ? (
        <group position={[0.32, 1.42, 0.25]} scale={cruz}>
          <Pieza forma="caja" medidas={[0.4, 0.055, 0.03]} color="#E0482B" rotacion={[0, 0, Math.PI / 4]} />
          <Pieza forma="caja" medidas={[0.4, 0.055, 0.03]} color="#E0482B" rotacion={[0, 0, -Math.PI / 4]} />
        </group>
      ) : null}

      <Etiqueta texto="se burla de ti" punto={[-0.1, 0.62, 0.06]} desplazamiento={[-0.52, 0.12, 0.3]} escala={etiqueta} alto={0.15} />
    </group>
  );
};

escenas.Escena4:
// Escena 5 (PASO 4 → 5): «Lo que suele funcionar es la presión. Una sopapa, pero bien usada.»
// La persona sorprendida se va, unas flechas de presión empujan sobre el desagüe y cae la
// sopapa roja junto al lavamanos con un destello. El tapón sigue a la vista dentro del sifón.
import React from 'react';
import {EscenaProps, Flecha, Etiqueta, Linea, aparecer, desaparecer, momento, mover, caer} from '../lib3d';
import {Persona2D, Efecto, Sombra} from '../lib25d';
import {Mundo, SopapaForma, POS_SOPAPA_LADO, PUNTOS} from './Mundo';

const PASO = 4;

export const Escena4: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];

  // Momentos de la voz
  const tLo = momento(palabras, fps, 'lo', 1);
  const tFunciona = momento(palabras, fps, 'funcionar', 20);
  const tPresion = momento(palabras, fps, 'presión', 47);
  const tSopapa = momento(palabras, fps, 'sopapa', 84);
  const tBien = momento(palabras, fps, 'bien', 109);
  const fin = duracion;

  // 1) Golpe inicial: el tapón "late" con ondas (sigue ahí, cerrado)
  const latido = aparecer(frame, tLo, 6) * desaparecer(frame, tLo + 26, 10);

  // 2) La persona sorprendida se va caminando a la izquierda (a 0,7 u/s)
  const tSale = tFunciona + 6;
  const camina = frame >= tSale;
  const personaX = -0.98 - Math.max(0, (frame - tSale) / fps) * 0.7;
  const personaVisible = personaX > -1.95;

  // 3) Flechas de presión sobre el desagüe
  const presion = aparecer(frame, tPresion, 10) * desaparecer(frame, tSopapa - 8, 10);
  const vaiven = Math.sin((frame - tPresion) * 0.4) * 0.05;

  // 4) Cae la sopapa y aterriza en la palabra "sopapa"
  const c = caer(frame, fps, tSopapa, 1.6);
  const resaltada = frame >= tSopapa && frame < tSopapa + 36;
  // pequeño balanceo de asentamiento y otro en "bien"
  const asienta = frame > tSopapa ? Math.exp(-(frame - tSopapa) / 8) * Math.sin((frame - tSopapa) / 2.2) * 0.12 : 0;
  const fb = frame - tBien;
  const meneo = fb > 0 ? Math.exp(-fb / 7) * Math.sin(fb / 1.8) * 0.18 : 0;
  const salto = fb > 0 ? Math.max(0, Math.sin(Math.min(1, fb / 10) * Math.PI)) * 0.06 : 0;
  const destello = frame >= tSopapa - 2 && frame < tSopapa + 28;
  const sombra = Math.min(1, c.escala) * (1 - Math.min(1, c.y / 1.6) * 0.6);

  // 5) Etiqueta de la sopapa y trayectoria punteada al desagüe ("bien usada")
  const etq = aparecer(frame, tSopapa + 2, 10) * desaparecer(frame, fin - 12, 10);
  const ruta = aparecer(frame, tBien, 12) * desaparecer(frame, fin - 10, 8);
  const pulsoCopa = frame >= tBien && frame < tBien + 30;

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['persona']}
        resaltar={latido > 0.5 ? ['tapon'] : []} />

      {/* el tapón late al inicio */}
      {latido > 0.01 ? (
        <Efecto tipo="ondas" posicion={[0, PUNTOS.tapon[1], 0.16]} tam={0.35 * latido} color={resalte} frame={frame} fps={fps} />
      ) : null}

      {/* persona de camiseta azul que se va */}
      {personaVisible ? (
        <group>
          <Persona2D pose={camina ? 'camina' : 'sorprendida'} color="#2F7FD0" alto={1.35}
            posicion={[personaX, 0, 0.12]} espejo={camina} frame={frame} fps={fps} />
          <Sombra posicion={[personaX, 0, 0.12]} radio={0.3} />
        </group>
      ) : null}

      {/* presión: flechas que empujan sobre el desagüe */}
      {presion > 0.01 ? (
        <group>
          {[-0.16, 0, 0.16].map((x, i) => (
            <Flecha key={x}
              desde={[x * 1.4, 1.62 + vaiven * (i % 2 ? -1 : 1), 0.05]}
              hasta={[x * 0.5, 1.12 + vaiven * (i % 2 ? -1 : 1), 0.03]}
              color={resalte} grosor={0.028} progreso={presion} />
          ))}
          <Efecto tipo="ondas" posicion={[0, 1.04, 0.1]} tam={0.4 * presion} color={resalte} frame={frame} fps={fps} />
        </group>
      ) : null}

      {/* la sopapa roja cae y queda de pie al lado */}
      {c.escala > 0.001 ? (
        <group>
          <group position={[POS_SOPAPA_LADO[0], POS_SOPAPA_LADO[1] + c.y + salto, POS_SOPAPA_LADO[2]]}
            rotation={[0, 0, -0.14 + c.giro + asienta + meneo]} scale={c.escala}>
            <SopapaForma paleta={paleta} frame={frame} resaltado={resaltada} resaltarCopa={pulsoCopa} />
          </group>
          <Sombra posicion={POS_SOPAPA_LADO} radio={0.22 * Math.max(0.3, sombra)} />
        </group>
      ) : null}
      {destello ? (
        <Efecto tipo="destello" posicion={[-0.6, 0.55, 0.55]} tam={0.5} color="#FFFFFF" frame={frame} fps={fps} />
      ) : null}
      {frame >= tSopapa && frame < tSopapa + 14 ? (
        <Efecto tipo="ondas" posicion={[POS_SOPAPA_LADO[0], 0.03, POS_SOPAPA_LADO[2]]} tam={0.45} color={resalte} frame={frame} fps={fps} />
      ) : null}

      {/* "bien usada": la ruta hacia el desagüe */}
      {ruta > 0.01 ? (
        <group>
          <Linea desde={[-0.5, 0.95, 0.45]} hasta={[-0.08, 1.12, 0.08]} grosor={0.012} color={resalte} discontinua progreso={ruta} />
          <Flecha desde={[-0.14, 1.12, 0.12]} hasta={[-0.02, 0.98, 0.03]} color={resalte} grosor={0.018} progreso={ruta} />
        </group>
      ) : null}

      <Etiqueta texto="la sopapa" punto={[-0.66, 0.14, 0.5]} desplazamiento={[-0.3, 0.62, 0.1]} escala={etq} />

      {/* asentamiento suave de la escena mientras habla */}
      <group position={[0, mover(frame, [0, fin], [0, 0]), 0]} />
    </group>
  );
};

escenas.Escena5:
// Escena 6: «Primero, tapa el rebose con un trapo mojado. Si no, la presión se escapa por ahí.»
// 3D: el lavamanos en corte (Mundo), el trapo. 2D: la mano, las gotas y las ondas del golpe.
// Flechas azules: la presión sale por el rebose y se pierde; con el trapo puesto, rebota hacia el tapón.
import React from 'react';
import {EscenaProps, Flecha, Etiqueta, Linea, Pieza, Brillo, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Mano, Efecto} from '../lib25d';
import {Mundo, Trapo, PUNTOS} from './Mundo';

const PASO = 5;

// Punto a lo largo de una polilínea (t de 0 a 1).
const enCamino = (camino: V3[], t: number): V3 => {
  const largos = camino.slice(1).map((p, i) => Math.hypot(p[0] - camino[i][0], p[1] - camino[i][1], p[2] - camino[i][2]));
  const total = largos.reduce((a, b) => a + b, 0);
  let d = Math.max(0, Math.min(1, t)) * total;
  for (let i = 0; i < largos.length; i++) {
    if (d <= largos[i] || i === largos.length - 1) {
      const k = largos[i] > 0 ? Math.min(1, d / largos[i]) : 0;
      const a = camino[i];
      const b = camino[i + 1];
      return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
    }
    d -= largos[i];
  }
  return camino[camino.length - 1];
};

// Subida por el tubo del rebose (desde el desagüe hasta el orificio).
const SUBIDA: V3[] = [
  [-0.1, 0.78, 0], [-0.22, 0.8, 0.02], [-0.41, 0.86, 0.08], [-0.41, 0.97, 0.18], [-0.32, 1.03, 0.28],
];
// Sin trapo: sale por el orificio y se pierde en el aire.
const ESCAPE: V3[] = [...SUBIDA, [-0.66, 1.24, 0.56]];
// Con trapo: choca y vuelve hacia el desagüe y el tapón.
const REBOTE: V3[] = [...SUBIDA, ...[...SUBIDA].reverse().slice(1), [0, 0.7, 0], [0, 0.62, 0]];

export const Escena5: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [naranja, , azul] = paleta.acentos;
  const tPrimero = momento(palabras, fps, 'primero', 1);
  const tTapa = momento(palabras, fps, 'tapa', 46);
  const tRebose = momento(palabras, fps, 'rebose', 56);
  const tTrapo = momento(palabras, fps, 'trapo', 77);
  const tMojado = momento(palabras, fps, 'mojado', 84);
  const tSi = momento(palabras, fps, 'si', 101);
  const tPresion = momento(palabras, fps, 'presión', 123);
  const tEscapa = momento(palabras, fps, 'escapa', 136);
  const fin = duracion;

  // --- presión que se escapa (desde el primer instante) ---
  const escapeVis = aparecer(frame, tPrimero, 6) * (1 - aparecer(frame, tTrapo - 4, 8));
  const pulsoEsc = ((frame - tPrimero) % 24) / 18;

  // --- mano con el trapo: entra, empuja en el rebose, se va ---
  const R = PUNTOS.rebose;
  const manoT = [tTapa - 12, tRebose, tTrapo - 6, tTrapo, tMojado + 4, tSi + 4];
  const manoX = mover(frame, manoT, [-1.25, -0.62, -0.58, -0.47, -0.5, -1.3]);
  const manoY = mover(frame, manoT, [1.35, 1.12, 1.1, 1.05, 1.06, 1.3]);
  const manoZ = mover(frame, manoT, [0.6, 0.5, 0.48, 0.4, 0.42, 0.6]);
  const manoVis = aparecer(frame, tTapa - 12, 8) * (1 - aparecer(frame, tSi, 6));
  // el trapo viaja en la mano hasta quedar metido en el rebose
  const suelto = frame >= tTrapo;
  const trapoOff: V3 = suelto ? [0, 0, 0] : [manoX + 0.17 - R[0], manoY - 0.04 - R[1], manoZ - 0.02 - R[2]];
  const trapoVis = aparecer(frame, tTapa - 12, 8);
  const aplasta = suelto ? 1 - 0.18 * Math.exp(-(frame - tTrapo) / 4) * Math.cos((frame - tTrapo) / 1.5) : 1;

  // --- presión que rebota en el trapo ---
  const reboteVis = aparecer(frame, tTrapo + 6, 8) * (1 - aparecer(frame, fin - 12, 10));
  const fuerte = 1 + 0.6 * Math.max(0, 1 - Math.abs(frame - tPresion - 6) / 14);
  const pulsoReb = ((frame - tTrapo) % 26) / 18;

  // --- «se escapa por ahí»: el camino viejo tachado ---
  const cruz = aparecer(frame, tEscapa, 7) * (1 - aparecer(frame, fin - 12, 10));
  const latido = 1 + 0.08 * Math.sin((frame - tEscapa) * 0.5) * cruz;

  const resaltar = frame >= tRebose && frame < tRebose + 40 ? ['rebose'] : [];
  const trapoResalta = frame >= tTrapo && frame < tTrapo + 38;
  const etiquetaRebose = aparecer(frame, tRebose, 8) * (1 - aparecer(frame, tMojado - 6, 6));
  const etiquetaTrapo = aparecer(frame, tMojado, 8) * (1 - aparecer(frame, fin - 14, 10));

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} resaltar={resaltar} />

      {/* Sin trapo: partículas y flecha que salen por el rebose y se pierden */}
      {escapeVis > 0.01 ? (
        <group>
          {[0, 0.2, 0.4, 0.6, 0.8].map((d) => {
            const t = (((frame - tPrimero) / 26 + d) % 1 + 1) % 1;
            const r = 0.022 * escapeVis * (t > 0.8 ? (1 - t) / 0.2 : 1);
            return r > 0.002 ? <Brillo key={d} posicion={enCamino(ESCAPE, t)} color={azul} radio={r} /> : null;
          })}
          <Flecha desde={[-0.36, 1.06, 0.33]} hasta={[-0.72, 1.3, 0.6]} color={azul} grosor={0.022 * escapeVis}
            progreso={Math.min(1, pulsoEsc) * escapeVis} />
          <Linea desde={[0, 0.74, 0.02]} hasta={[-0.1, 0.78, 0.02]} grosor={0.01} color={azul} discontinua progreso={escapeVis} />
        </group>
      ) : null}

      {/* Mano 2D que mete el trapo mojado */}
      {manoVis > 0.01 ? (
        <Mano pose="agarra" espejo posicion={[manoX, manoY, manoZ]} ancho={0.55} escala={manoVis} frame={frame} fps={fps} />
      ) : null}
      {trapoVis > 0.01 ? (
        <group position={trapoOff}>
          <group position={R} scale={[trapoVis * (2 - aplasta), trapoVis * aplasta, trapoVis]}>
            <group position={[-R[0], -R[1], -R[2]]}>
              <Trapo paleta={paleta} frame={frame} resaltado={trapoResalta} />
            </group>
          </group>
          {frame < tSi ? (
            <Efecto tipo="gotas" posicion={[R[0] - 0.02, R[1] - 0.06, R[2] + 0.05]} tam={0.16} color={azul} frame={frame} fps={fps} />
          ) : null}
        </group>
      ) : null}

      {/* Con trapo: la presión choca y vuelve al desagüe, contra el tapón */}
      {reboteVis > 0.01 ? (
        <group>
          {[0, 0.25, 0.5, 0.75].map((d) => {
            const t = (((frame - tTrapo) / 34 + d) % 1 + 1) % 1;
            return <Brillo key={d} posicion={enCamino(REBOTE, t)} color={azul} radio={0.02 * reboteVis * fuerte} />;
          })}
          <Flecha desde={[-0.37, 0.99, 0.21]} hasta={[-0.2, 0.83, 0.05]} color={azul} grosor={0.02 * reboteVis * fuerte}
            progreso={Math.min(1, pulsoReb) * reboteVis} />
          <Flecha desde={[0.03, 0.8, 0.04]} hasta={[0.03, 0.64, 0.04]} color={azul} grosor={0.02 * reboteVis * fuerte}
            progreso={Math.min(1, Math.max(0, pulsoReb - 0.3) * 1.4) * reboteVis} />
        </group>
      ) : null}
      {frame >= tPresion && frame < tPresion + 30 ? (
        <Efecto tipo="ondas" posicion={[R[0], R[1], R[2] + 0.06]} tam={0.3} color={naranja} frame={frame - tPresion} fps={fps} />
      ) : null}

      {/* «Si no, se escapa por ahí»: el camino de salida, tachado con una cruz roja */}
      {cruz > 0.01 ? (
        <group>
          <Linea desde={[-0.36, 1.07, 0.33]} hasta={[-0.66, 1.26, 0.55]} grosor={0.012} color="#D93A2B" discontinua progreso={cruz} />
          <group position={[-0.6, 1.22, 0.52]} scale={cruz * latido}>
            <Pieza forma="caja" medidas={[0.2, 0.04, 0.03]} color="#D93A2B" rotacion={[0, 0, 0.785]} />
            <Pieza forma="caja" medidas={[0.2, 0.04, 0.03]} color="#D93A2B" rotacion={[0, 0, -0.785]} />
          </group>
        </group>
      ) : null}

      {/* Rótulos cortos, a la izquierda y lejos del lavamanos */}
      <Etiqueta texto="rebose" punto={[R[0] - 0.03, R[1] + 0.02, R[2]]} desplazamiento={[-0.38, 0.46, 0.1]} escala={etiquetaRebose} />
      <Etiqueta texto="trapo mojado" punto={[R[0] - 0.04, R[1] + 0.03, R[2]]} desplazamiento={[-0.3, 0.48, 0.1]} escala={etiquetaTrapo} />
    </group>
  );
};

escenas.Escena6:
// Escena 7 · «Segundo, deja agua cubriendo toda la ventosa. Sin agua, solo empujas aire.»
// Mundo paso 6 → paso 7: la sopapa sale de su lado y se asienta en el desagüe, bajo el agua.
// Viñeta del error (en seco: el aire se escapa por el borde, cruz roja) y se queda la correcta.
import React from 'react';
import {EscenaProps, Pieza, Flecha, Etiqueta, Cartel, aparecer, momento, mover} from '../lib3d';
import {Efecto, Sombra} from '../lib25d';
import {Mundo, SopapaForma, POS_SOPAPA_LADO, POS_SOPAPA_DESAGUE, PUNTOS} from './Mundo';

const PI = Math.PI;
const ROJO_CRUZ = '#D83A2E';

export const Escena6: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];
  const tSeg = momento(palabras, fps, 'segundo', 1);
  const tDeja = momento(palabras, fps, 'deja', 27);
  const tAgua = momento(palabras, fps, 'agua', 37);
  const tCubre = momento(palabras, fps, 'cubriendo', 47);
  const tVentosa = momento(palabras, fps, 'ventosa', 77);
  const tSin = momento(palabras, fps, 'sin', 108);
  const tEmpuja = momento(palabras, fps, 'empujas', 130);
  const tAire = momento(palabras, fps, 'aire', 142);
  const tFin = Math.min(duracion - 12, tAire + 22);

  // ---- sopapa: anticipa, sube en arco por encima del borde y se sienta en el desagüe ----
  const t0 = Math.max(tSeg + 8, tDeja - 6);
  const t1 = Math.max(t0 + 6, tDeja + 2);
  const t2 = Math.max(t1 + 6, tAgua + 2);
  const t3 = Math.max(t2 + 6, tCubre);
  const [lx, ly, lz] = POS_SOPAPA_LADO;
  const [dx, dy, dz] = POS_SOPAPA_DESAGUE;
  const sx = mover(frame, [t0, t1, t2, t3], [lx, lx, -0.3, dx]);
  const sy = mover(frame, [t0, t1, t2, t3], [ly, ly - 0.03, 1.5, dy]);
  const sz = mover(frame, [t0, t1, t2, t3], [lz, lz, 0.22, dz]);
  const sRot = mover(frame, [t0, t1, t2, t3], [-0.14, -0.2, 0.15, 0]);
  // pequeño salto al nombrar el paso (primer golpe)
  const salto = frame < t0 ? Math.max(0, Math.sin((frame / 10) * PI)) * 0.06 * (frame < 10 ? 1 : 0) : 0;
  // asentamiento: rebota un poco al tocar el fondo
  const asienta = frame > t3 ? Math.exp(-(frame - t3) / 5) * Math.sin((frame - t3) / 1.8) * -0.025 : 0;
  const despega = aparecer(frame, t1, 6);
  const sombraLado = 0.22 * (1 - despega);

  const resaltaSopapa = frame < t0 + 2;
  const resaltaAgua = frame >= tAgua && frame < tAgua + 40;
  const resaltaCopa = frame >= tVentosa && frame < tVentosa + 40;

  // ---- sello de agua en el borde de la copa (la forma correcta) ----
  const sello = aparecer(frame, tVentosa, 10) * (1 - aparecer(frame, tSin - 4, 10));
  const pulso = 1 + Math.sin(frame * 0.4) * 0.04;

  // ---- viñeta del error: ventosa en seco ----
  const vin = aparecer(frame, tSin, 9) * (1 - aparecer(frame, tFin, 10));
  const pop = vin * (1 + Math.sin(Math.min(1, aparecer(frame, tSin, 12)) * PI) * 0.12);
  const bombeo = mover(frame, [tEmpuja - 4, tEmpuja + 3, tEmpuja + 9, tAire, tAire + 6], [0, -0.05, 0, -0.05, 0]);
  const sale = aparecer(frame, tEmpuja, 8);
  const escapa = aparecer(frame, tAire, 14);
  const burbujaX = 0.04 + 0.08 * sale + 0.06 * escapa;
  const burbujaY = -0.13 + 0.03 * sale + 0.22 * escapa + Math.abs(Math.sin(frame * 0.5)) * 0.015 * sale;
  const burbujaR = 0.03 + 0.012 * Math.sin(frame * 0.6) * sale;
  const cruz = aparecer(frame, tAire, 7);
  const textoAire = aparecer(frame, tAire, 8) * vin;

  return (
    <group>
      <Mundo
        paso={6}
        frame={frame}
        fps={fps}
        paleta={paleta}
        ocultar={['sopapa']}
        resaltar={resaltaAgua ? ['agua'] : []}
      />

      {/* la sopapa en movimiento */}
      <group position={[sx, sy + salto + asienta, sz]} rotation={[0, 0, sRot]}>
        <SopapaForma paleta={paleta} frame={frame} resaltado={resaltaSopapa} resaltarCopa={resaltaCopa} />
      </group>
      {sombraLado > 0.02 ? <Sombra posicion={POS_SOPAPA_LADO} radio={sombraLado} /> : null}

      {/* gotas al bajar y ondas al hundirse en el agua */}
      {frame >= t2 && frame < t3 + 4 ? (
        <Efecto tipo="gotas" posicion={[sx, sy - 0.05, sz + 0.05]} tam={0.2} color={resalte} frame={frame} fps={fps} />
      ) : null}
      {frame >= t3 - 2 && frame < t3 + 24 ? (
        <Efecto tipo="ondas" posicion={[0, 1.05, 0.08]} tam={0.45} color={resalte} frame={frame - t3} fps={fps} />
      ) : null}

      {/* el agua sella el borde de la ventosa */}
      {sello > 0.01 ? (
        <group position={PUNTOS.desague} scale={[sello * pulso, 1, sello * pulso]}>
          <Pieza forma="toro" medidas={[0.14, 0.018]} color={resalte} brillo={resalte} intensidadBrillo={0.5} rotacion={[PI / 2, 0, 0]} posicion={[0, 0.01, 0]} />
        </group>
      ) : null}
      <Flecha desde={[0.3, 1.03, 0.12]} hasta={[0.15, 0.9, 0.04]} color={resalte} grosor={0.016} progreso={sello} />
      <Flecha desde={[-0.3, 1.03, 0.12]} hasta={[-0.15, 0.9, 0.04]} color={resalte} grosor={0.016} progreso={sello} />
      <Etiqueta texto="sella el borde" punto={[0.14, 0.88, 0.02]} desplazamiento={[0.48, 0.42, 0.2]} escala={sello} />

      {/* viñeta: en seco solo empujas aire */}
      {vin > 0.01 ? (
        <group position={[-0.8, 1.42, 0.3]} scale={pop}>
          <Pieza forma="caja" medidas={[0.56, 0.56, 0.02]} color="#F7F4EE" posicion={[0, 0.03, -0.04]} />
          <Pieza forma="caja" medidas={[0.5, 0.03, 0.02]} color={ROJO_CRUZ} posicion={[0, 0.3, -0.025]} contorno={false} />
          {/* fondo seco de la poceta y su desagüe */}
          <Pieza forma="caja" medidas={[0.46, 0.04, 0.1]} color="#CFC8BC" posicion={[0, -0.17, 0]} />
          <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.012]} color="#4A4440" posicion={[0, -0.146, 0.01]} contorno={false} />
          {/* sopapa pequeña que bombea en seco */}
          <group position={[0, -0.15 + bombeo, 0.02]} scale={0.42}>
            <SopapaForma paleta={paleta} frame={frame} />
          </group>
          {/* el aire se escapa por el borde */}
          {sale > 0.01 ? (
            <Pieza forma="esfera" medidas={[burbujaR]} color="#FFFFFF" opacidad={0.75} posicion={[burbujaX, burbujaY, 0.05]} escala={[1.2 - 0.2 * escapa, 0.85 + 0.2 * escapa, 1]} />
          ) : null}
          <Flecha desde={[0.06, -0.14, 0.06]} hasta={[0.2, -0.05, 0.06]} color="#9AA3AA" grosor={0.01} progreso={sale} />
          <Flecha desde={[-0.06, -0.14, 0.06]} hasta={[-0.2, -0.05, 0.06]} color="#9AA3AA" grosor={0.01} progreso={sale} />
          {escapa > 0.05 ? (
            <Efecto tipo="burbujas" posicion={[0.14, 0.02, 0.06]} tam={0.16} color="#FFFFFF" frame={frame} fps={fps} />
          ) : null}
          {/* cruz roja */}
          {cruz > 0.01 ? (
            <group position={[0, 0.03, 0.1]} scale={cruz}>
              <Pieza forma="caja" medidas={[0.5, 0.05, 0.02]} color={ROJO_CRUZ} rotacion={[0, 0, PI / 4]} />
              <Pieza forma="caja" medidas={[0.5, 0.05, 0.02]} color={ROJO_CRUZ} rotacion={[0, 0, -PI / 4]} />
            </group>
          ) : null}
        </group>
      ) : null}
      {textoAire > 0.01 ? (
        <Cartel texto="solo aire" posicion={[-0.8, 1.04, 0.32]} alto={0.15} fondo="transparent" colorTexto="#FFFFFF" borde="#1B1B1F" escala={textoAire} />
      ) : null}
    </group>
  );
};
